//! 🥞️ Original baking keeps raw output and complete inverse history through bounded construction and cancellation.
use super::*;
use semio_framework_plugin::artifact_app_laws::OriginalWorkFixture;
use protocol::{ColdMutation,Mutation};
fn fixture()->serde_json::Value{serde_json::from_str(include_str!("../../🧪️tests/🧫️fixtures/🔣️.json")).unwrap()}
fn policy()->serde_json::Value{serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap()}
fn stock()->RetainedCloneGrant{let f=policy();let p=&f["stock"];RetainedCloneGrant{maximum_items:p["maximumItems"].as_u64().unwrap() as usize,maximum_copy_bytes:p["maximumCopyBytes"].as_u64().unwrap() as usize,maximum_capacity_bytes:p["maximumCapacityBytes"].as_u64().unwrap() as usize,maximum_release_bytes:p["maximumReleaseBytes"].as_u64().unwrap() as usize,maximum_depth:p["maximumDepth"].as_u64().unwrap() as usize}}
fn loan()->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:32768,maximum_capacity_bytes:1<<20,maximum_release_bytes:1<<20,maximum_depth:4096}}
fn caller()->OriginalWorkFixture{OriginalWorkFixture::with_source(semio_framework_job::OperationId(999),semio_framework_job::Generation(17),stock(),||Some(1),u64::MAX,1<<24)}
fn document(capacity:usize)->RasterSnapshot{let f=fixture();let mut document=semio_s_artifact_raster_raster_model::io::text::snapshot::snapshot_wire_codec::empty_raster_snapshot();document.layers=semio_framework_pack_json::from_json_str(&f["layers"].to_string(),semio_framework_pack_json::JsonMemberPolicy::Reject).unwrap();for(key,value)in f["images"].as_object().unwrap(){let image=semio_s_artifact_raster_raster_model::semio_image_from_rgba8(value["width"].as_u64().unwrap() as u32,value["height"].as_u64().unwrap() as u32,serde_json::from_value(value["pixels"].clone()).unwrap());document.assets.insert(key.clone(),semio_s_artifact_raster_raster_model::mint_raster_image_child(key,&image)).unwrap();}let image=semio_s_artifact_raster_raster_model::semio_image_from_rgba8(1,1,vec![255;4]);for index in document.assets.len()..capacity{let key=format!("spare-{index}");document.assets.insert(key.clone(),semio_s_artifact_raster_raster_model::mint_raster_image_child(&key,&image)).unwrap();}document}
fn close<const MERGE:bool>(caller:&mut OriginalWorkFixture,owner:&mut LayerBakeOwner<MERGE>){owner.cancel();for turn in 0..100_000{if owner.terminal_is_empty(){return}caller.turn(loan(),|cx|{let demand=owner.close_demands(32768)?;semio_framework_job::close_original_retained_step(cx,demand,|grant|owner.close_step(grant))?;Ok(())}).unwrap();assert!(turn<99_999);}panic!("original bake fixture close did not settle")}
#[test]
fn original_bake_preserves_exact_raw_pixels_capacity_and_inverse_history(){let fixture=fixture();for capacity in policy()["assetCapacities"].as_array().unwrap(){let mut caller=caller();let mut document=document(capacity.as_u64().unwrap() as usize);let before=document.clone();let command=RasterCommand::FlattenLayers(super::super::FlattenLayers{name:"Flattened Image".into()});let mut owner=LayerBakeOwner::<false>::new(&command,&document).unwrap();for turn in 0..100_000{if owner.output_ready(){break}let demand=owner.demands(32768).unwrap();assert_eq!(owner.advance(&command,&document,32768,RetainedCloneGrant::default()).result.unwrap().progress(),Default::default());assert_eq!(owner.demands(32768).unwrap(),demand);caller.turn(loan(),|cx|{let turn=owner.advance(&command,&document,32768,cx.retained_grant());semio_framework_job::receive_original_retained_work(cx,turn)?;Ok(())}).unwrap();assert!(turn<99_999);}let mut emit=None;caller.turn(loan(),|cx|{let turn=owner.take_emit(cx.retained_grant());let work=turn.work;let(value,progress)=turn.result.unwrap().unwrap();emit=Some(value);semio_framework_job::receive_original_retained_work(cx,RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(progress)),work})?;Ok(())}).unwrap();close(&mut caller,&mut owner);let emit=emit.unwrap();let mut inverses=Vec::new();for mutation in &emit.artifact_mutations{inverses.push(mutation.inverse(&document).unwrap());let(next,messages)=semio_framework_os_kernel::apply_mutation(&document,mutation).unwrap();assert!(messages.is_empty());semio_s_artifact_raster_raster_model::snapshot::retire_raster_snapshot(std::mem::replace(&mut document,next));assert!(document.assets.len()<=64);}let RasterLayerNode::Pixel{image_key:Some(key),transform,..}=&document.layers[0]else{panic!("baked pixel layer is attached")};assert!(key.starts_with("image-"));let image=document.assets.get(key).unwrap().local_owner::<SemioImageSnapshot>().unwrap();assert_eq!(serde_json::to_value(&image.frames[0].rgba8).unwrap(),fixture["expected"]["pixels"]);assert_eq!((transform.x,transform.y),(-3.0,4.5));for inverse in inverses.into_iter().rev().flatten(){let(next,messages)=semio_framework_os_kernel::apply_mutation(&document,&inverse).unwrap();assert!(messages.is_empty());semio_s_artifact_raster_raster_model::snapshot::retire_raster_snapshot(std::mem::replace(&mut document,next));caller.retire_owned(inverse,loan());}assert_eq!(document,before);caller.retire_owned(emit.artifact_mutations,loan());semio_s_artifact_raster_raster_model::snapshot::retire_raster_snapshot(document);semio_s_artifact_raster_raster_model::snapshot::retire_raster_snapshot(before);caller.finish();}}
#[test]
fn original_bake_cancellation_never_publishes_private_output(){for cut in policy()["cancelAfterTurns"].as_array().unwrap().iter().map(|value|value.as_u64().unwrap()){let mut caller=caller();let document=document(3);let before=document.clone();let command=RasterCommand::FlattenLayers(super::super::FlattenLayers{name:"Image".into()});let mut owner=LayerBakeOwner::<false>::new(&command,&document).unwrap();for _ in 0..cut{if owner.output_ready(){break}caller.turn(loan(),|cx|{let turn=owner.advance(&command,&document,32768,cx.retained_grant());semio_framework_job::receive_original_retained_work(cx,turn)?;Ok(())}).unwrap();}close(&mut caller,&mut owner);assert_eq!(document,before);assert!(owner.take_emit(loan()).result.unwrap().is_none());semio_s_artifact_raster_raster_model::snapshot::retire_raster_snapshot(document);semio_s_artifact_raster_raster_model::snapshot::retire_raster_snapshot(before);caller.finish();}}
